class Solution {
public:
    int equalSubstring(string s, string t, int maxCost) {
        int l = 0, cost = 0, best = 0;
        for (int r = 0; r < (int)s.size(); r++) {
            cost += abs(s[r] - t[r]);
            while (cost > maxCost) {
                cost -= abs(s[l] - t[l]);
                l++;
            }
            best = max(best, r - l + 1);
        }
        return best;
    }
};
